        environment,
        command=command,
        env=self._run_env(instruction),
    )

def populate_context_post_run(self, context: AgentContext) -> None:
    trajectory, totals = self._build_trajectory()
    if not self._session_files():
        self._warn_no_session_files()
    trajectory_path = self.logs_dir / "trajectory.json"
    trajectory_path.write_text(json.dumps(trajectory, indent=2), encoding="utf-8")

    context.n_input_tokens = totals["input"]
    context.n_output_tokens = totals["output"]
    context.cost_usd = totals["cost"]

def _build_trajectory(self) -> tuple[dict[str, Any], dict[str, float]]:
    session_files = self._session_files()
    if not session_files:
        return self._empty_trajectory(), {"input": 0, "output": 0, "cost": 0.0}

    events: list[dict[str, Any]] = []
    for line in session_files[-1].read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        events.append(json.loads(line))

    steps: list[dict[str, Any]] = []
    session_id = session_files[-1].stem
    model_name = ""
    total_input = 0
    total_output = 0
    total_cost = 0.0
    step_id = 1

    for event in events:
        etype = event.get("type", "")
        data = event.get("data") or {}
        if isinstance(data, str):
            try:
                data = json.loads(data)
            except json.JSONDecodeError:
                data = {}
        timestamp = event.get("timestamp") or event.get("ts")
        session_id = event.get("session_id", session_id)

        if etype == "session.start":
            model_name = data.get("model", model_name)
            prompt = data.get("prompt", "")
            if prompt:
                steps.append(
                    {
                        "step_id": step_id,
                        "timestamp": timestamp,
                        "source": "user",
                        "message": prompt,
                    }
                )
                step_id += 1
            continue

        if etype == "llm.response":
            usage = data.get("usage") or {}
            cost = data.get("cost_usd") or 0.0
            if cost == -1:
                cost = 0.0
            prompt_tokens = usage.get("input", 0) or 0
            completion_tokens = usage.get("output", 0) or 0
            total_input += prompt_tokens
            total_output += completion_tokens
            total_cost += cost
            model_name = data.get("model", model_name)

            tool_calls = []
            for tc in data.get("tool_calls") or []:
                name = tc.get("name", "")
                tool_calls.append(
                    {
                        "tool_call_id": tc.get("id", ""),
                        "function_name": name,
                        "arguments": tc.get("arguments", {}),
                        "name": name,
                        "result": "",
                        "error": "",
                    }
                )

            step: dict[str, Any] = {
                "step_id": step_id,
                "timestamp": timestamp,
                "source": "agent",
                "message": data.get("content", "") or "(tool use)",
                "model_name": model_name,
                "tool_calls": tool_calls or None,
                "metrics": {
                    "prompt_tokens": prompt_tokens,
                    "completion_tokens": completion_tokens,
                    "cost_usd": cost,
                },
            }
            steps.append(step)
            step_id += 1
            continue

        if etype == "tool.call":
            tool_name = data.get("tool", "")
            output = data.get("output", "")
            err = data.get("error", "")
            for step in reversed(steps):
                if step.get("source") != "agent":
                    continue
                tool_calls = step.get("tool_calls") or []
                for tc in tool_calls:
                    if tc.get("name") == tool_name and not tc.get("result"):
                        tc["result"] = output
                        tc["error"] = err
                        observation = step.setdefault("observation", {"results": []})
                        observation["results"].append(
                            {
                                "source_call_id": tc.get("tool_call_id"),
                                "content": err or output,
                            }
                        )
                        break
                else:
                    continue
                break

    trajectory = {
        "schema_version": "ATIF-v1.6-ddx",
        "session_id": session_id,
        "agent": {
            "name": "fiz",
            "version": self.version() or "unknown",
            "model_name": model_name,
        },
        "steps": steps,
        "final_metrics": {
            "total_prompt_tokens": total_input,
            "total_completion_tokens": total_output,
            "total_cost_usd": total_cost,
            "total_steps": len(steps),
        },
    }
    return trajectory, {
        "input": total_input,
        "output": total_output,
        "cost": total_cost,
    }

def _session_files(self) -> list[Path]:
    return sorted(
        (self.logs_dir / "sessions").rglob("*.jsonl"),
        key=lambda p: p.stat().st_mtime,
    )

def _warn_no_session_files(self) -> None:
    expected = self.logs_dir / "sessions"
    contents = self._logs_dir_contents()
    warning = (
        "warning: no fiz session JSONL found for trajectory build; "
        f"expected path: {expected}; actual /logs/agent contents:\n{contents}"
    )
    logger.warning(warning)
    log_path = self.logs_dir / "fiz.txt"
    with log_path.open("a", encoding="utf-8") as f:
        f.write("\n" + warning + "\n")

def _logs_dir_contents(self) -> str:
    if not self.logs_dir.exists():
        return f"{self.logs_dir} does not exist"
    entries: list[str] = []
    for path in sorted(self.logs_dir.rglob("*")):
        try:
            rel = path.relative_to(self.logs_dir)
        except ValueError:
            rel = path
        suffix = "/" if path.is_dir() else ""
        entries.append(f"/logs/agent/{rel}{suffix}")
        if len(entries) >= 200:
            entries.append("... truncated after 200 entries")
            break
    return "\n".join(entries) if entries else "(empty)"

def _empty_trajectory(self) -> dict[str, Any]:
    return {
        "schema_version": "ATIF-v1.6-ddx",
        "session_id": str(uuid.uuid4()),
        "agent": {
            "name": "fiz",
            "version": self.version() or "unknown",
            "model_name": self.model_name or "",
        },
        "steps": [],
        "final_metrics": {
            "total_prompt_tokens": 0,
            "total_completion_tokens": 0,
            "total_cost_usd": 0.0,
            "total_steps": 0,
        },
    }

"""fiz adapter command builder for the TerminalBench matrix."""

from __future__ import annotations

import os
import shutil
from typing import Any

from .base import (
    BaseAdapter,
    BenchmarkProfile,
    CommandSpec,
    InstallSpec,
    empty_telemetry,
    jsonl_objects,
    redact_values,
)


class Agent(BaseAdapter):
    name = "fiz"

    def install(self) -> InstallSpec:
        return InstallSpec(["install", "-m", "0755", "${HARBOR_AGENT_ARTIFACT}", "/installed-agent/fiz"])

    def apply_profile(self, profile: BenchmarkProfile) -> CommandSpec:
        env: dict[str, str] = {
            "FIZEAU_BASE_URL": profile.provider.base_url,
            "FIZEAU_MODEL": profile.provider.model,
            "FIZEAU_API_KEY": os.environ.get(profile.provider.api_key_env, ""),
        }
        if "openrouter" in profile.provider.base_url:
            env["FIZEAU_PROVIDER"] = "openrouter"
        elif profile.provider.type not in ("openai-compat",):
            env["FIZEAU_PROVIDER"] = profile.provider.type
        # Forward sampling params so fiz reads them via FIZEAU_* env overrides.
        sampling = getattr(profile, "sampling", None) or {}
        if isinstance(sampling, dict):
            if (t := sampling.get("temperature")) is not None:
                env["FIZEAU_TEMPERATURE"] = str(t)
            if (v := sampling.get("top_p")) is not None:
                env["FIZEAU_TOP_P"] = str(v)
            if (v := sampling.get("top_k")) is not None:
                env["FIZEAU_TOP_K"] = str(int(v))
            if (v := sampling.get("min_p")) is not None:
                env["FIZEAU_MIN_P"] = str(v)
        return CommandSpec(argv=[], env=env, stdin=None)

    def command(self, profile: BenchmarkProfile, prompt: str, workdir: str | None = None) -> CommandSpec:
        applied = self.apply_profile(profile)
        binary = shutil.which("fiz") or "/installed-agent/fiz"
        argv = [
            binary,
            "--json",
            "--preset",
            "default",
            "--work-dir",
            workdir or ".",
            "-p",
            prompt,
        ]
        return CommandSpec(argv=argv, env=applied.env, stdin="", cwd=workdir)

    def parse_telemetry(self, stream: str) -> dict[str, Any]:
        telemetry = empty_telemetry()
        for event in jsonl_objects(stream):
            if event.get("type") not in {"session.end", "final"}:
                continue
            data = event.get("data")
            if isinstance(data, dict):
                usage = data.get("usage") or {}
                telemetry["input_tokens"] = usage.get("input") or usage.get("input_tokens")
                telemetry["output_tokens"] = usage.get("output") or usage.get("output_tokens")
                if data.get("status") == "failed":
                    telemetry["process_outcome"] = "harness_crash"
        telemetry["wall_seconds"] = 0.0
        return telemetry

    def redact_secrets(self, text: str, env: dict[str, str], profile: BenchmarkProfile | None = None) -> str:
        values = list(env.values())
        if profile is not None:
            values.extend([
                env.get(profile.provider.api_key_env, ""),
                profile.provider.base_url,
            ])
        return redact_values(text, values)

"""Shared adapter primitives for the TerminalBench harness matrix.

The matrix runner imports one adapter module per harness. Each adapter exposes
an ``Agent`` object with install, command, apply_profile, parse_telemetry, and
redact_secrets methods. The helpers here keep that contract small and testable
without invoking paid APIs or live harness binaries.
"""

from __future__ import annotations

from dataclasses import dataclass, field
import json
from typing import Any


@dataclass(frozen=True)
class ProviderProfile:
    type: str
    model: str
    base_url: str
    api_key_env: str


@dataclass(frozen=True)
class SamplingProfile:
    temperature: float | None = None
    reasoning: str = ""


@dataclass(frozen=True)
class LimitsProfile:
    max_output_tokens: int | None = None
    context_tokens: int | None = None


@dataclass(frozen=True)
class BenchmarkProfile:
    id: str
    provider: ProviderProfile
    sampling: SamplingProfile = field(default_factory=SamplingProfile)
    limits: LimitsProfile = field(default_factory=LimitsProfile)

    @classmethod
    def from_mapping(cls, raw: dict[str, Any]) -> "BenchmarkProfile":
        provider = raw.get("provider") or {}
        sampling = raw.get("sampling") or {}
        limits = raw.get("limits") or {}
        return cls(
            id=str(raw.get("id") or ""),
            provider=ProviderProfile(
                type=str(provider.get("type") or ""),
                model=str(provider.get("model") or ""),
                base_url=str(provider.get("base_url") or ""),
                api_key_env=str(provider.get("api_key_env") or ""),
            ),
            sampling=SamplingProfile(
                temperature=sampling.get("temperature"),
                reasoning=str(sampling.get("reasoning") or ""),
            ),
            limits=LimitsProfile(
                max_output_tokens=limits.get("max_output_tokens"),
                context_tokens=limits.get("context_tokens"),
            ),
        )


@dataclass(frozen=True)
class InstallSpec:
    argv: list[str]


@dataclass(frozen=True)
class CommandSpec:
    argv: list[str]
    env: dict[str, str] = field(default_factory=dict)
    stdin: str | None = None
    cwd: str | None = None
    notes: list[str] = field(default_factory=list)


def redact_values(text: str, values: list[str]) -> str:
    out = text
    for value in values:
        if value:
            out = out.replace(value, "[REDACTED]")
    return out


def empty_telemetry() -> dict[str, Any]:
    return {
        "process_outcome": "completed",
        "grading_outcome": "ungraded",
        "reward": None,
        "turns": None,
        "tool_calls": None,
        "tool_call_errors": None,
        "input_tokens": None,
        "output_tokens": None,
        "cached_input_tokens": None,
        "retried_input_tokens": None,
        "wall_seconds": None,
    }


def jsonl_objects(stream: str) -> list[dict[str, Any]]:
    objects: list[dict[str, Any]] = []
    for line in stream.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            parsed = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(parsed, dict):
            objects.append(parsed)
    return objects


def usage_from_event(event: dict[str, Any]) -> dict[str, int | None]:
    usage = event.get("usage")
    if not isinstance(usage, dict):
        message = event.get("message")
        if isinstance(message, dict):
            usage = message.get("usage")
    if not isinstance(usage, dict):
        partial = event.get("partial")
        if isinstance(partial, dict):
            usage = partial.get("usage")
    if not isinstance(usage, dict):
        return {"input_tokens": None, "output_tokens": None}
    return {
        "input_tokens": usage.get("input_tokens") or usage.get("prompt_tokens"),
        "output_tokens": usage.get("output_tokens") or usage.get("completion_tokens"),
    }


class BaseAdapter:
    name = ""

    def install(self) -> InstallSpec:
        raise NotImplementedError

    def apply_profile(self, profile: BenchmarkProfile) -> CommandSpec:
        raise NotImplementedError

    def command(self, profile: BenchmarkProfile, prompt: str, workdir: str | None = None) -> CommandSpec:
        raise NotImplementedError

    def parse_telemetry(self, stream: str) -> dict[str, Any]:
        raise NotImplementedError

    def redact_secrets(self, text: str, env: dict[str, str], profile: BenchmarkProfile | None = None) -> str:
        values = list(env.values())
        if profile is not None:
            values.append(env.get(profile.provider.api_key_env, ""))
        return redact_values(text, values)

